import {
  Autocomplete,
  Box,
  Grid,
  InputAdornment,
  TextField,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import React, { useEffect, useMemo, useRef, useState } from 'react';
import SearchIcon from '@mui/icons-material/Search';
import LocalShippingOutlinedIcon from '@mui/icons-material/LocalShippingOutlined';
import { useVirtualizer } from '@tanstack/react-virtual';
import { useSelector } from 'react-redux';
import {
  selectSupplierNameOrMobile,
  selectReceiptNo,
} from '../../store/BasketSelector';
import { addMobileReceiptID } from '../../store/BasketSlice';
import { useAppDispatch } from '../../../../store/hooks';
import { useGetSupplierByMobileQuery } from '../../../posApi';
import { ICustomerMobileDatails } from '../../../../core/Interface/customer.interface';
import usePurchase from '../../usePurchase';
import { IProductData } from '../../../../core/Interface/product.interface';
import { getPriceFormatWithoutCurrency } from '../../../../core/utils';
import { addItem, BasketItem } from '../../store/BasketSlice';

const TEAL = '#0F8B8D';
const NAVY = '#0F1D4D';
const ITEM_H = 44;
const MAX_VISIBLE = 8;

const VirtualListbox = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLElement>
>(function VirtualListbox({ children, style, ...other }, ref) {
  const items = React.Children.toArray(children);
  const scrollRef = useRef<HTMLDivElement>(null);

  const virtualizer = useVirtualizer({
    count: items.length,
    estimateSize: () => ITEM_H,
    getScrollElement: () => scrollRef.current,
    overscan: 5,
  });

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = 0;
  }, [items.length]);

  const height = Math.min(items.length * ITEM_H, ITEM_H * MAX_VISIBLE);

  return (
    <div ref={ref} style={{ ...style, overflow: 'hidden', padding: '4px 0' }} {...other}>
      <div ref={scrollRef} style={{ height, overflowY: 'auto' }}>
        <div style={{ height: virtualizer.getTotalSize(), position: 'relative' }}>
          {virtualizer.getVirtualItems().map((vi) => (
            <div
              key={vi.index}
              style={{ left: 0, position: 'absolute', right: 0, top: 0, transform: `translateY(${vi.start}px)` }}
            >
              {items[vi.index]}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
});

const SupplierSearch = () => {
  const dispatch = useAppDispatch();
  const supplierMobile = useSelector(selectSupplierNameOrMobile);
  const receiptNo = useSelector(selectReceiptNo);
  const [supplierInput, setSupplierInput] = useState('');
  const [mobileOptions, setMobileOptions] = useState<string[]>([]);
  const [searchValue, setSearchValue] = useState('');

  const { data: supplierData, isFetching: fetchingSupplier } = useGetSupplierByMobileQuery(
    supplierInput,
    { skip: !supplierInput },
  );

  useEffect(() => {
    if (supplierData) {
      const suppliers = (supplierData.data as { suppliers: ICustomerMobileDatails[] })?.suppliers;
      if (suppliers) {
        setMobileOptions(suppliers.map((s) => s.mobile));
      }
    }
  }, [supplierData]);

  useEffect(() => {
    if (supplierMobile) setSupplierInput(supplierMobile);
  }, [supplierMobile]);

  const { categoryMemo, currencyCode } = usePurchase();

  const productMemo = useMemo(
    () => Object.entries(categoryMemo).flatMap(([, arr]) => arr.map((obj) => ({ ...obj }))),
    [categoryMemo],
  );

  const filteredProducts = useMemo(() => {
    if (!searchValue) return productMemo;
    const q = searchValue.toLowerCase().trim();
    return productMemo.filter(
      (p) => p.name?.toLowerCase().includes(q) || p.code?.toLowerCase().includes(q),
    );
  }, [productMemo, searchValue]);

  const handleProductChange = (
    _event: React.SyntheticEvent,
    newValue: string | IProductData | null,
  ) => {
    if (newValue && typeof newValue === 'object' && 'id' in newValue) {
      const product = newValue as IProductData;
      const basketItem: BasketItem = {
        id: product.id,
        name: product.name,
        code: product.code,
        sellingPrice: product.unitPrice,
        cost: product.unitPrice,
        price: product.unitPrice,
        discount: 0,
        isDiscountPercentage: false,
        total: product.unitPrice,
        quanity: 1,
        totalQty: 1,
        freeQty: 0,
        discountAmount: 0,
        totalDiscountAmount: 0,
      };
      dispatch(addItem(basketItem));
      setSearchValue('');
    }
  };

  return (
    <Box>
      <Grid container spacing={1} sx={{ fontWeight: 800, pb: 1 }}>
        {/* Supplier search */}
        <Grid item md={6}>
          <Autocomplete
            freeSolo
            getOptionLabel={(option) => option}
            loading={fetchingSupplier}
            noOptionsText="No supplier found"
            onChange={(_e, val) => {
              if (val) {
                setSupplierInput(val);
                dispatch(addMobileReceiptID({ supplierNameOrMobile: val, receiptNo: receiptNo ?? '' }));
              }
            }}
            onInputChange={(_e, val) => {
              setSupplierInput(val);
            }}
            options={mobileOptions}
            value={supplierInput || ''}
            renderInput={(params) => (
              <TextField
                {...params}
                InputProps={{
                  ...params.InputProps,
                  startAdornment: (
                    <InputAdornment position="start">
                      <LocalShippingOutlinedIcon sx={{ color: TEAL, fontSize: 17 }} />
                    </InputAdornment>
                  ),
                }}
                autoComplete="off"
                fullWidth
                onChange={(e) => setSupplierInput(e.target.value)}
                placeholder="Supplier mobile…"
                size="small"
                sx={{
                  '& .MuiOutlinedInput-input': { fontSize: 13 },
                  '& .MuiOutlinedInput-root': {
                    backgroundColor: '#fff',
                    borderRadius: '10px',
                    '& fieldset': { borderColor: alpha(NAVY, 0.18) },
                    '&.Mui-focused fieldset': { borderColor: TEAL, borderWidth: '1.5px' },
                    '&:hover fieldset': { borderColor: alpha(TEAL, 0.5) },
                  },
                }}
              />
            )}
            sx={{ width: '100%' }}
          />
        </Grid>

        {/* Product search */}
        <Grid item md={6}>
          <Autocomplete
            ListboxComponent={VirtualListbox as React.ComponentType<React.HTMLAttributes<HTMLElement>>}
            freeSolo
            getOptionLabel={(option) => typeof option === 'string' ? option : option.name || ''}
            id="purchase-product-search"
            inputValue={searchValue}
            isOptionEqualToValue={(option, value) => {
              if (typeof option === 'string' || typeof value === 'string') return false;
              return option.id === value.id;
            }}
            onChange={handleProductChange}
            onInputChange={(_e, v) => setSearchValue(v)}
            options={filteredProducts}
            renderInput={(params) => (
              <TextField
                {...params}
                InputProps={{
                  ...params.InputProps,
                  startAdornment: (
                    <InputAdornment position="start">
                      <SearchIcon sx={{ color: TEAL, fontSize: 17 }} />
                    </InputAdornment>
                  ),
                  type: 'search',
                }}
                fullWidth
                placeholder="Search name or code…"
                size="small"
                sx={{
                  '& .MuiOutlinedInput-input': { fontSize: 13 },
                  '& .MuiOutlinedInput-root': {
                    backgroundColor: '#fff',
                    borderRadius: '10px',
                    '& fieldset': { borderColor: alpha(NAVY, 0.18) },
                    '&.Mui-focused fieldset': { borderColor: TEAL, borderWidth: '1.5px' },
                    '&:hover fieldset': { borderColor: alpha(TEAL, 0.5) },
                  },
                }}
              />
            )}
            renderOption={(props, option) => {
              if (typeof option === 'string') return <li {...props}>{option}</li>;
              return (
                <li {...props} key={option.id} style={{ borderRadius: '8px', cursor: 'pointer', padding: '6px 10px' }}>
                  <Box sx={{ alignItems: 'center', display: 'flex', gap: 1, width: '100%' }}>
                    <Box sx={{ background: TEAL, borderRadius: '2px', flexShrink: 0, height: 26, width: 3 }} />
                    <Box sx={{ flex: 1, minWidth: 0 }}>
                      <Typography sx={{ color: NAVY, fontSize: 12, fontWeight: 700, lineHeight: 1.3, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                        {option.name}
                      </Typography>
                      {option.code && (
                        <Typography sx={{ color: alpha(NAVY, 0.42), fontSize: 10, lineHeight: 1.2 }}>
                          {option.code}
                        </Typography>
                      )}
                    </Box>
                    {option.unitPrice !== undefined && (
                      <Typography sx={{ color: TEAL, flexShrink: 0, fontSize: 11, fontVariantNumeric: 'tabular-nums', fontWeight: 800 }}>
                        {currencyCode} {getPriceFormatWithoutCurrency(option.unitPrice)}
                      </Typography>
                    )}
                  </Box>
                </li>
              );
            }}
            slotProps={{
              paper: {
                sx: {
                  border: `1px solid ${alpha(TEAL, 0.15)}`,
                  borderRadius: '12px',
                  boxShadow: `0 8px 32px ${alpha(NAVY, 0.16)}`,
                  mt: 0.5,
                  '& .MuiAutocomplete-option': {
                    '&:hover, &.Mui-focused': { background: alpha(TEAL, 0.08) },
                    '&[aria-selected="true"]': { background: alpha(TEAL, 0.12) },
                  },
                },
              },
            }}
            sx={{ width: '100%' }}
            value={null}
          />
        </Grid>
      </Grid>

      {/* Supplier / receipt info strip */}
      {(supplierMobile || receiptNo) && (
        <Box sx={{ display: 'flex', gap: 2, px: 0.5, pb: 0.5 }}>
          {supplierMobile && (
            <Typography sx={{ fontSize: 11, fontWeight: 600, color: TEAL }}>
              Supplier: {supplierMobile}
            </Typography>
          )}
          {receiptNo && (
            <Typography sx={{ fontSize: 11, fontWeight: 600, color: alpha(NAVY, 0.6) }}>
              Receipt #: {receiptNo}
            </Typography>
          )}
        </Box>
      )}
    </Box>
  );
};

export default React.memo(SupplierSearch);
