import {
  Box,
  Button,
  Checkbox,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Divider,
  FormControlLabel,
  IconButton,
  InputAdornment,
  Slide,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import React, { useEffect } from 'react';
import { TransitionProps } from '@mui/material/transitions';
import { appColors } from '../../../../../theme/appColors';
import { BasketItem, addItem, removeItem } from '../../../store/BasketSlice';
import { useAppDispatch } from '../../../../../store/hooks';
import { useFormik } from 'formik';
import CloseRoundedIcon from '@mui/icons-material/CloseRounded';
import DeleteOutlineIcon from '@mui/icons-material/DeleteOutline';
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import RemoveCircleOutlineIcon from '@mui/icons-material/RemoveCircleOutline';
import react from 'react';

interface IPurchaseBasketItemEditModel {
  item: BasketItem;
  open: boolean;
  handleClose: () => void;
}

const inputFieldSx = {
  '& .MuiOutlinedInput-root': {
    backgroundColor: alpha(appColors.white, 0.92),
    borderRadius: '4px',
    '& fieldset': { borderColor: alpha(appColors.blueGreyishLight[80], 0.16) },
    '&:hover fieldset': { borderColor: alpha('#2563EB', 0.28) },
    '&.Mui-focused': { boxShadow: `0 0 0 4px ${alpha('#2563EB', 0.10)}` },
    '&.Mui-focused fieldset': { borderColor: '#2563EB' },
  },
};

const labelSx = {
  color: '#142352',
  fontSize: '0.86rem',
  fontWeight: 700,
  mb: 0.8,
};

const Transition = React.forwardRef(function Transition(
  props: TransitionProps & { children: React.ReactElement<string, string> },
  ref: React.Ref<unknown>,
) {
  return <Slide
    direction="up"
    ref={ref}
    {...props}
         />;
});

const PurchaseBasketItemEditModel: React.FC<IPurchaseBasketItemEditModel> = ({
  item,
  open,
  handleClose,
}) => {
  const dispatch = useAppDispatch();

  const formik = useFormik({
    enableReinitialize: true,
    initialValues: {
      quanity: item.quanity ?? 1,
      freeQty: item.freeQty ?? 0,
      price: item.price ?? 0,
      discount: item.discount ?? 0,
      discountAsPercentage: item.isDiscountPercentage ?? false,
      sellingPrice: item.sellingPrice ?? 0,
    },
    onSubmit: (values) => {
      const totalUnits = values.quanity;
      const pricePerUnit = values.price ?? 0;
      const discount = values.discount ?? 0;
      const totalPrice = pricePerUnit * totalUnits;
      const discountAmount = values.discountAsPercentage
        ? (discount / 100) * totalPrice
        : discount * totalUnits;
      const costPerUnit = totalUnits > 0 ? (totalPrice - discountAmount) / totalUnits : 0;
      const total = totalUnits * costPerUnit;

      const updated: BasketItem = {
        ...item,
        quanity: values.quanity,
        freeQty: values.freeQty,
        totalQty: values.quanity + values.freeQty,
        price: values.price,
        discount: values.discount,
        isDiscountPercentage: values.discountAsPercentage,
        cost: costPerUnit,
        sellingPrice: values.sellingPrice,
        discountAmount: pricePerUnit - costPerUnit,
        totalDiscountAmount: (pricePerUnit - costPerUnit) * values.quanity,
        total,
      };
      dispatch(addItem(updated));
      handleClose();
    },
    validate: () => ({}),
  });

  const price = formik.values.price ?? 0;
  const qty = formik.values.quanity ?? 1;
  const discount = formik.values.discount ?? 0;
  const totalPrice = price * qty;
  const discountAmount = formik.values.discountAsPercentage
    ? (discount / 100) * totalPrice
    : discount * qty;
  const costPerUnit = qty > 0 ? (totalPrice - discountAmount) / qty : 0;
  const lineTotal = costPerUnit * qty;

  return (
    <Dialog
      PaperProps={{
        component: 'form',
        noValidate: true,
        onSubmit: formik.handleSubmit,
        sx: {
          background: 'linear-gradient(180deg, rgba(255,255,255,0.98) 0%, rgba(248,251,255,0.96) 100%)',
          border: `1px solid ${alpha(appColors.blueGreyishLight[80], 0.1)}`,
          borderRadius: '8px',
          boxShadow: '0 30px 80px rgba(15,23,42,0.28)',
          maxWidth: 'calc(100vw - 32px)',
          overflow: 'hidden',
          width: 520,
        },
      }}
      TransitionComponent={Transition}
      fullWidth
      maxWidth={false}
      onClose={handleClose}
      open={open}
    >
      {/* Header */}
      <DialogTitle sx={{ p: 0 }}>
        <Box
          sx={{
            background: 'linear-gradient(135deg, rgba(239,246,255,0.96) 0%, rgba(224,236,255,0.98) 54%, rgba(255,247,237,0.96) 100%)',
            borderBottom: `1px solid ${alpha(appColors.blueGreyishLight[80], 0.1)}`,
            px: { xs: 2.5, md: 4 },
            py: { xs: 2.5, md: 3 },
          }}
        >
          <Box sx={{ alignItems: 'flex-start', display: 'flex', gap: 2, justifyContent: 'space-between' }}>
            <Box sx={{ minWidth: 0 }}>
              <Typography sx={{ color: alpha(appColors.blueGreyishLight[80], 0.62), fontSize: '0.74rem', letterSpacing: '0.16em', mb: 0.9, textTransform: 'uppercase' }}>
                Purchase Item
              </Typography>
              <Typography sx={{ color: '#142352', fontSize: { xs: '1.2rem', md: '1.5rem' }, fontWeight: 700, lineHeight: 1.2, maxWidth: 360, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                {item.name}
              </Typography>
              {item.code && (
                <Typography sx={{ color: alpha(appColors.blueGreyishLight[80], 0.7), fontSize: '0.84rem', mt: 0.5 }}>
                  Code: {item.code}
                </Typography>
              )}
            </Box>
            <IconButton
              onClick={handleClose}
              sx={{
                backgroundColor: alpha(appColors.white, 0.72),
                border: `1px solid ${alpha(appColors.blueGreyishLight[80], 0.1)}`,
                color: alpha(appColors.blueGreyishLight[80], 0.72),
                mr: -0.8,
                mt: -0.5,
                '&:hover': { backgroundColor: alpha(appColors.white, 0.94) },
              }}
            >
              <CloseRoundedIcon />
            </IconButton>
          </Box>
        </Box>
      </DialogTitle>

      {/* Content */}
      <DialogContent sx={{ p: 0 }}>
        <Box
          sx={{
            background: 'radial-gradient(circle at top right, rgba(37,99,235,0.04), transparent 28%), linear-gradient(180deg, rgba(255,255,255,0.92) 0%, rgba(248,251,255,0.88) 100%)',
            px: { xs: 2.5, md: 4 },
            py: { xs: 2.5, md: 3 },
          }}
        >
          {/* Quantity */}
          <Box sx={{ mb: 3 }}>
            <Typography sx={labelSx}>Quantity</Typography>
            <Stack
              alignItems="center"
              direction="row"
              spacing={1}
            >
              <IconButton
                onClick={() => formik.setFieldValue('quanity', Math.max((formik.values.quanity ?? 1) - 1, 1))}
                size="small"
                sx={{ border: `1.5px solid ${alpha('#2563EB', 0.24)}`, borderRadius: '4px', color: '#2563EB', p: 0.5, '&:hover': { background: alpha('#2563EB', 0.06) } }}
              >
                <RemoveCircleOutlineIcon fontSize="small" />
              </IconButton>
              <TextField
                autoComplete="off"
                inputProps={{ min: 1, step: 'any', style: { fontWeight: 700, fontSize: 16, textAlign: 'center' } }}
                size="small"
                sx={{ width: 100, ...inputFieldSx }}
                type="number"
                {...formik.getFieldProps('quanity')}
              />
              <IconButton
                onClick={() => formik.setFieldValue('quanity', (formik.values.quanity ?? 1) + 1)}
                size="small"
                sx={{ border: `1.5px solid ${alpha('#2563EB', 0.24)}`, borderRadius: '4px', color: '#2563EB', p: 0.5, '&:hover': { background: alpha('#2563EB', 0.06) } }}
              >
                <AddCircleOutlineIcon fontSize="small" />
              </IconButton>
              <Box sx={{ ml: 2 }}>
                <Typography sx={{ ...labelSx, mb: 0 }}>Free Qty</Typography>
                <TextField
                  autoComplete="off"
                  inputProps={{ min: 0, step: 'any', style: { fontWeight: 600, fontSize: 14, textAlign: 'center' } }}
                  size="small"
                  sx={{ width: 80, ...inputFieldSx }}
                  type="number"
                  {...formik.getFieldProps('freeQty')}
                />
              </Box>
            </Stack>
          </Box>

          <Divider sx={{ mb: 3 }} />

          {/* Price */}
          <Box sx={{ mb: 3 }}>
            <Typography sx={labelSx}>Purchase Price</Typography>
            <TextField
              InputProps={{ inputProps: { min: 0 } }}
              autoComplete="off"
              fullWidth
              placeholder="0.00"
              size="small"
              sx={inputFieldSx}
              type="number"
              inputProps={{ step: 'any' }}
              {...formik.getFieldProps('price')}
            />
          </Box>

          {/* Discount */}
          <Box sx={{ mb: 3 }}>
            <Typography sx={labelSx}>Discount</Typography>
            <Stack
              alignItems="center"
              direction="row"
              spacing={2}
            >
              <TextField
                InputProps={{
                  endAdornment: formik.values.discountAsPercentage
                    ? (
                      <InputAdornment position="end">
                        <Typography sx={{ color: alpha(appColors.blueGreyishLight[80], 0.72), fontSize: 13, fontWeight: 600 }}>%</Typography>
                      </InputAdornment>
                    )
                    : undefined,
                  inputProps: { min: 0 },
                }}
                autoComplete="off"
                placeholder="0.00"
                size="small"
                sx={{ flex: 1, ...inputFieldSx }}
                type="number"
                inputProps={{ step: 'any' }}
                {...formik.getFieldProps('discount')}
              />
              <FormControlLabel
                control={
                  <Checkbox
                    checked={formik.values.discountAsPercentage}
                    name="discountAsPercentage"
                    onChange={() => {
                      formik.setFieldValue('discountAsPercentage', !formik.values.discountAsPercentage);
                      formik.setFieldValue('discount', 0, false);
                    }}
                    size="small"
                    sx={{ p: 0.5 }}
                  />
                }
                label={<Typography sx={{ color: '#142352', fontSize: '0.82rem', fontWeight: 600 }}>Percentage (%)</Typography>}
                sx={{ m: 0 }}
              />
            </Stack>
          </Box>

          {/* Selling Price */}
          <Box sx={{ mb: 3 }}>
            <Typography sx={labelSx}>Selling Price</Typography>
            <TextField
              InputProps={{ inputProps: { min: 0 } }}
              autoComplete="off"
              fullWidth
              placeholder="0.00"
              size="small"
              sx={inputFieldSx}
              type="number"
              inputProps={{ step: 'any' }}
              {...formik.getFieldProps('sellingPrice')}
            />
          </Box>

          {/* Live summary */}
          <Box
            sx={{
              alignItems: 'center',
              background: alpha('#059669', 0.06),
              border: `1px solid ${alpha('#059669', 0.18)}`,
              borderRadius: '6px',
              display: 'flex',
              justifyContent: 'space-between',
              px: 2.5,
              py: 1.5,
            }}
          >
            <Box>
              <Typography sx={{ color: alpha('#059669', 0.8), fontSize: '0.7rem', fontWeight: 600, letterSpacing: '1px', textTransform: 'uppercase' }}>
                Cost / Unit
              </Typography>
              <Typography sx={{ color: '#065f46', fontSize: '1rem', fontWeight: 700 }}>
                {costPerUnit.toFixed(2)}
              </Typography>
            </Box>
            <Box sx={{ textAlign: 'right' }}>
              <Typography sx={{ color: alpha('#059669', 0.8), fontSize: '0.7rem', fontWeight: 600, letterSpacing: '1px', textTransform: 'uppercase' }}>
                Line Total × {qty}
              </Typography>
              <Typography sx={{ color: '#065f46', fontSize: '1.3rem', fontWeight: 800 }}>
                {lineTotal.toFixed(2)}
              </Typography>
            </Box>
          </Box>
        </Box>
      </DialogContent>

      {/* Footer */}
      <DialogActions sx={{ p: 0 }}>
        <Box
          sx={{
            alignItems: { xs: 'stretch', md: 'center' },
            backgroundColor: alpha('#F8FAFC', 0.94),
            borderTop: `1px solid ${alpha(appColors.blueGreyishLight[80], 0.08)}`,
            display: 'flex',
            flexDirection: { xs: 'column', md: 'row' },
            gap: 2,
            justifyContent: 'space-between',
            px: { xs: 2.5, md: 4 },
            py: 2.3,
            width: '100%',
          }}
        >
          <Button
            onClick={() => { dispatch(removeItem(item.id)); handleClose(); }}
            startIcon={<DeleteOutlineIcon fontSize="small" />}
            sx={{ borderColor: alpha('#B42318', 0.4), borderRadius: '4px', color: '#B42318', fontWeight: 700, height: 46, px: 2.5, textTransform: 'none' }}
            variant="outlined"
          >
            Remove
          </Button>
          <Box sx={{ display: 'flex', flexDirection: { xs: 'column-reverse', sm: 'row' }, gap: 1.5, width: { xs: '100%', md: 'auto' } }}>
            <Button
              onClick={handleClose}
              sx={{ borderColor: alpha('#142352', 0.22), borderRadius: '4px', color: '#142352', fontWeight: 700, height: 46, minWidth: 120, px: 3, textTransform: 'none' }}
              variant="outlined"
            >
              Cancel
            </Button>
            <Button
              autoFocus
              sx={{ background: 'linear-gradient(135deg, #2563EB 0%, #1D4ED8 100%)', borderRadius: '4px', boxShadow: '0 12px 24px rgba(37,99,235,0.22)', fontWeight: 700, height: 46, minWidth: 150, px: 3, textTransform: 'none', '&:hover': { background: 'linear-gradient(135deg, #1D4ED8 0%, #1E40AF 100%)' } }}
              type="submit"
              variant="contained"
            >
              Update Item
            </Button>
          </Box>
        </Box>
      </DialogActions>
    </Dialog>
  );
};

export default React.memo(PurchaseBasketItemEditModel);
